USE CakesDB; GO  CREATE TRIGGER trg_block_order ON Orders INSTEAD OF INSERT AS BEGIN  SET NOCOUNT ON;      IF EXISTS (         SELECT 1         FROM Orders o         WHERE o.client_id IN (SELECT client_id FROM inserted)           AND o.total_cost > o.paid_amount     )     BEGIN         RAISERROR ('Клієнт має неоплачені замовлення', 16, 1);         RETURN;     END;      INSERT INTO Orders     (order_number, order_date, completion_date, status, total_cost, paid_amount, client_id, chef_id)     SELECT     order_number, order_date, completion_date, status, total_cost, 0, client_id, chef_id     FROM inserted; END; Go  CREATE TRIGGER trg_update_payment ON Payments AFTER INSERT AS BEGIN     SET NOCOUNT ON;      UPDATE o     SET o.paid_amount = p.total_paid     FROM Orders o     JOIN (         SELECT order_id, SUM(amount) AS total_paid         FROM Payments         GROUP BY order_id     ) p ON o.id = p.order_id     JOIN inserted i ON i.order_id = o.id; END; Go  UPDATE Orders SET paid_amount = 100 WHERE client_id = 2;  UPDATE Payments SET amount = 100 WHERE order_id IN (     SELECT id     FROM Orders     WHERE client_id = 2 );   INSERT INTO Orders (order_number, status, total_cost, paid_amount, client_id, chef_id) VALUES (101, 'new', 100, 0, 2, 1);  INSERT INTO Payments (payment_number, payment_date, amount, payment_type, order_id) VALUES (999, GETDATE(), 343.30, 'card', 2);   SELECT id,        client_id,        total_cost,        paid_amount,        total_cost - paid_amount AS debt FROM Orders;  